INSERT INTO public.advice (id, course, study_tip, mistake, resources, author_id, difficulty_rating, upvotes, tags, is_anonymous) VALUES
('ad111111-1111-1111-1111-111111111111', 'Calculus I', 'Practice derivatives daily, even if just 15 minutes. Use the chain rule breakdown method: identify outer function, inner function, then apply the rule step by step.', 'Don''t skip the algebra review! I thought I could jump straight into limits but my algebra was rusty and it hurt me all semester.', 'Khan Academy Calculus playlist, Professor Leonard on YouTube, Paul''s Online Math Notes', 'ad111111-1111-1111-1111-111111111111', 'intermediate', 34, ARRAY['calculus', 'derivatives', 'study-tips'], true),
('ad222222-2222-2222-2222-222222222222', 'Data Structures & Algorithms', 'Implement each data structure from scratch at least once. Don''t just memorize - understand WHY each operation has its time complexity.', 'I relied too heavily on memorizing Big O notations without understanding the underlying mechanics. During interviews, I couldn''t explain my reasoning.', 'LeetCode, Cracking the Coding Interview book, Visualgo.net for algorithm visualization', 'ad222222-2222-2222-2222-222222222222', 'hard', 28, ARRAY['programming', 'algorithms', 'interview-prep'], true),
('ad333333-3333-3333-3333-333333333333', 'Organic Chemistry', 'Draw mechanisms by hand repeatedly. Use different colored pens for electron movement. Make flashcards for each reaction type with conditions and products.', 'I tried to memorize reactions without understanding electron flow. Failed my first midterm because I couldn''t adapt to new reaction variations.', 'Organic Chemistry as a Second Language by David Klein, Master Organic Chemistry website', 'ad333333-3333-3333-3333-333333333333', 'hard', 19, ARRAY['chemistry', 'mechanisms', 'memorization'], true),
('ad444444-4444-4444-4444-444444444444', 'Statistics 101', 'Always check your assumptions before running statistical tests. Create a checklist: normality, independence, equal variance. Visualize your data first!', 'Jumped straight into t-tests without checking if my data was normally distributed. Got completely wrong conclusions on my final project.', 'R for Data Science book, StatQuest YouTube channel, Khan Academy Statistics', 'ad444444-4444-4444-4444-444444444444', 'beginner', 16, ARRAY['statistics', 'assumptions', 'data-analysis'], true),
('ad555555-5555-5555-5555-555555555555', 'Linear Algebra', 'Visualize transformations! Every matrix represents a transformation in space. Use online tools to see how matrices stretch, rotate, and shear vectors.', 'I memorized formulas without understanding what matrices actually DO. Eigenvectors made no sense until I visualized them as special directions.', '3Blue1Brown Essence of Linear Algebra series, Khan Academy Linear Algebra', 'ad555555-5555-5555-5555-555555555555', 'intermediate', 22, ARRAY['math', 'linear-algebra', 'visualization'], true),
('ad666666-6666-6666-6666-666666666666', 'Introduction to Psychology', 'Connect concepts to your own life experiences. Psychology makes more sense when you can relate studies to real situations you''ve encountered.', 'Tried to memorize every study and researcher name without understanding the underlying principles. Bombed the application questions.', 'Crash Course Psychology, Psychology textbook companion website, flashcards for key terms', 'ad666666-6666-6666-6666-666666666666', 'beginner', 18, ARRAY['psychology', 'study-methods', 'application'], true);
INSERT INTO public.course_ratings (id, course_name, professor, difficulty, workload_hours, rating, review, rater_id) VALUES
('cr111111-1111-1111-1111-111111111111', 'CS 161: Data Structures', 'Dr. Smith', 'hard', 15, 4, 'Challenging but rewarding course. Dr. Smith explains concepts clearly and provides great coding examples. Heavy workload but you learn a lot.', 'cr111111-1111-1111-1111-111111111111'),
('cr222222-2222-2222-2222-222222222222', 'MATH 21A: Calculus', 'Prof. Johnson', 'intermediate', 10, 5, 'Excellent professor! Makes calculus concepts intuitive. Office hours are super helpful. Exams are fair if you do the homework.', 'cr222222-2222-2222-2222-222222222222'),
('cr333333-3333-3333-3333-333333333333', 'CHEM 51A: Organic Chemistry', 'Dr. Williams', 'hard', 20, 3, 'Very difficult course. Dr. Williams knows the material but goes through it quickly. Definitely attend discussion sections and form study groups.', 'cr333333-3333-3333-3333-333333333333'),
('cr444444-4444-4444-4444-444444444444', 'PSYC 1: Introduction to Psychology', 'Prof. Davis', 'easy', 8, 4, 'Great introductory course! Prof. Davis uses interesting real-world examples. Lots of reading but material is fascinating.', 'cr444444-4444-4444-4444-444444444444'),
('cr555555-5555-5555-5555-555555555555', 'MATH 51: Linear Algebra', 'Prof. Chen', 'intermediate', 12, 5, 'Brilliant professor! Prof. Chen makes abstract concepts concrete with amazing visualizations. Do the practice problems!', 'cr555555-5555-5555-5555-555555555555'),
('cr666666-6666-6666-6666-666666666666', 'ECON 1A: Microeconomics', 'Dr. Martinez', 'intermediate', 8, 4, 'Great intro to econ concepts. Dr. Martinez uses current events to make theories relevant. Midterms are fair but final is tough.', 'cr666666-6666-6666-6666-666666666666');
INSERT INTO public.scholarships (id, title, description, amount, deadline, requirements, application_url, submitted_by) VALUES
('s1111111-1111-1111-1111-111111111111', 'STEM Excellence Scholarship', 'Supporting outstanding students in Science, Technology, Engineering, and Mathematics fields. Open to undergraduates with strong academic performance.', '$5,000', '2024-04-15', 'Minimum 3.5 GPA, STEM major, essay submission, letter of recommendation', 'https://example.com/stem-scholarship', 's1111111-1111-1111-1111-111111111111'),
('s2222222-2222-2222-2222-222222222222', 'First-Generation College Student Award', 'Supporting students who are the first in their family to attend college. Financial need and academic merit considered.', '$3,000', '2024-05-01', 'First-generation college student, financial need demonstration, personal statement', 'https://example.com/first-gen-scholarship', 's2222222-2222-2222-2222-222222222222'),
('s3333333-3333-3333-3333-333333333333', 'Psychology Research Grant', 'Funding for undergraduate psychology students conducting original research projects with faculty mentorship.', '$2,500', '2024-03-30', 'Psychology major, research proposal, faculty mentor agreement, minimum 3.0 GPA', 'https://example.com/psych-research-grant', 's3333333-3333-3333-3333-333333333333'),
('s4444444-4444-4444-4444-444444444444', 'Women in Engineering Scholarship', 'Empowering women pursuing engineering degrees. Supports tuition, books, and research opportunities.', '$4,000', '2024-06-01', 'Female student, engineering major, minimum 3.0 GPA, leadership experience essay', 'https://example.com/women-engineering', 's4444444-4444-4444-4444-444444444444'),
('s5555555-5555-5555-5555-555555555555', 'Mathematics Excellence Award', 'Recognizing outstanding achievement in mathematical studies and research potential.', '$3,500', '2024-05-15', 'Mathematics major, minimum 3.7 GPA, professor recommendation, proof portfolio', 'https://example.com/math-excellence', 's5555555-5555-5555-5555-555555555555');